package org.jsoup;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.net.URL;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import org.jsoup.Jsoup;
import org.jsoup.helper.DataUtil;
import org.jsoup.helper.HttpConnection;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Whitelist;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;

@RunWith(Parameterized.class)
public class Jsoup_isValid_TriageGen1Test {

    private String bodyHtml;
    private Whitelist whitelist;

    public Jsoup_isValid_TriageGen1Test(String bodyHtml, Whitelist whitelist) {
        this.bodyHtml = bodyHtml;
        this.whitelist = whitelist;
    }

    @Parameterized.Parameters
    public static Collection<Object[]> data() {
        return Arrays.asList(
            new Object[]{ "<p>Hello World!</p>", Whitelist.none() },
            new Object[]{ "<p>Hello World!</p><script>alert('XSS')</script>", Whitelist.none() },
            new Object[]{ "<p>Hello World!</p>", Whitelist.relaxed() },
            new Object[]{ "<p>Hello World!</p><script>alert('XSS')</script>", Whitelist.relaxed() },
            new Object[]{ "<p>Hello World!</p>", Whitelist.basic() },
            new Object[]{ "<p>Hello World!</p><script>alert('XSS')</script>", Whitelist.basic() },
            new Object[]{ "<p>Hello World!</p>", Whitelist.legitimate() },
            new Object[]{ "<p>Hello World!</p><script>alert('XSS')</script>", Whitelist.legitimate() }
        );
    }

    @Test
    public void testIsValid() {
        Document doc = Jsoup.parseBodyFragment(bodyHtml);
        Cleaner cleaner = new Cleaner(whitelist);
        boolean isValid = cleaner.isValid(doc);
        assertTrue(isValid);
    }

    @Test
    public void testIsValid_XSS() {
        Document doc = Jsoup.parseBodyFragment(bodyHtml);
        Cleaner cleaner = new Cleaner(whitelist);
        boolean isValid = cleaner.isValid(doc);
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_InvalidHtml() {
        Document doc = Jsoup.parseBodyFragment("<script>alert('XSS')</script>");
        Cleaner cleaner = new Cleaner(whitelist);
        boolean isValid = cleaner.isValid(doc);
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_Null() {
        Document doc = null;
        Cleaner cleaner = new Cleaner(whitelist);
        boolean isValid = cleaner.isValid(doc);
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_NullWhitelist() {
        Document doc = Jsoup.parseBodyFragment("<p>Hello World!</p>");
        Cleaner cleaner = new Cleaner(null);
        boolean isValid = cleaner.isValid(doc);
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_Empty() {
        Document doc = Jsoup.parseBodyFragment("");
        Cleaner cleaner = new Cleaner(whitelist);
        boolean isValid = cleaner.isValid(doc);
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_NoClosingTag() {
        Document doc = Jsoup.parseBodyFragment("<p>Hello World!");
        Cleaner cleaner = new Cleaner(whitelist);
        boolean isValid = cleaner.isValid(doc);
        assertFalse(isValid);
    }

    @Test
    public void testIsValid_NoOpeningTag() {
        Document doc = Jsoup.parseBodyFragment("</p>Hello World!");
        Cleaner cleaner = new Cleaner(whitelist);
        boolean isValid = cleaner.isValid(doc);
        assertFalse(isValid);
    }
}
